arguments.command:
python3 -c "import json; d=json.load(open('/work/input.json')); seen=set(); accepted=[]; duplicates=[]; mismatches=[]; total=0; repeat_seen=set();
for x in d['invoices']:
    i=x['id']
    if i in seen:
        if i not in repeat_seen: duplicates.append(i); repeat_seen.add(i)
        continue
    seen.add(i); c=x['quantity']*x['unit_cents']
    if c==x['declared_cents']: accepted.append(i); total+=c
    else: mismatches.append({'id':i,'declared_cents':x['declared_cents'],'computed_cents':c})
out={'accepted_ids':accepted,'duplicate_ids':duplicates,'mismatches':mismatches,'accepted_total_cents':total}; json.dump(out,open('/work/result.json','w'),separators=(',',':'))"
